def choose_move(observation):
    # Defensive access: default to empty dict/list if keys missing
    grid = observation.get('grid', [])
    position = observation.get('position', (0, 0))
    # Extract relevant info, with default values
    resources = observation.get('resources', [])
    enemies = observation.get('enemies', [])
    territory_map = observation.get('territory', [])
    resource_positions = resources if isinstance(resources, list) else []

    # Helper functions
    def is_in_bounds(x, y):
        return 0 <= y < len(grid) and 0 <= x < len(grid[0]) if grid else False

    def get_cell(x, y):
        if is_in_bounds(x, y):
            return grid[y][x]
        return None

    def move_towards(target_x, target_y):
        curr_x, curr_y = position
        dx = dy = 0
        if target_x > curr_x:
            dx = 1
        elif target_x < curr_x:
            dx = -1
        if target_y > curr_y:
            dy = 1
        elif target_y < curr_y:
            dy = -1
        # Prioritize horizontal movement if both needed
        if dx != 0:
            if is_in_bounds(curr_x + dx, curr_y):
                cell = get_cell(curr_x + dx, curr_y)
                if cell != 'obstacle':
                    return dx, 0
        if dy != 0:
            if is_in_bounds(curr_x, curr_y + dy):
                cell = get_cell(curr_x, curr_y + dy)
                if cell != 'obstacle':
                    return 0, dy
        # Stay put if blocked
        return 0, 0

    # Decide target based on observation type
    target_x = target_y = None

    if resource_positions:
        # Resource collection: go to closest resource
        min_dist = float('inf')
        for res_x, res_y in resource_positions:
            dist = abs(res_x - position[0]) + abs(res_y - position[1])
            if dist < min_dist:
                min_dist = dist
                target_x, target_y = res_x, res_y
        dx, dy = move_towards(target_x, target_y)
        return [dx, dy]

    elif enemies:
        # Pursuit/Evasion: simple approach: move away if enemy close, else chase
        enemy_positions = enemies
        # Check if any enemy nearby
        for e_x, e_y in enemy_positions:
            dist = abs(e_x - position[0]) + abs(e_y - position[1])
            if dist <= 3:
                # Evade: move away from enemy
                dx = position[0] - e_x
                dy = position[1] - e_y
                # Normalize to -1, 0, 1
                dx = max(-1, min(1, dx))
                dy = max(-1, min(1, dy))
                # Check if move is free
                new_x = position[0] + dx
                new_y = position[1] + dy
                if is_in_bounds(new_x, new_y):
                    cell = get_cell(new_x, new_y)
                    if cell != 'obstacle':
                        return [dx, dy]
        # No immediate threat: pursue closest enemy
        min_dist = float('inf')
        target_enemy = None
        for e_x, e_y in enemy_positions:
            dist = abs(e_x - position[0]) + abs(e_y - position[1])
            if dist < min_dist:
                min_dist = dist
                target_enemy = (e_x, e_y)
        if target_enemy is not None:
            dx, dy = move_towards(target_enemy[0], target_enemy[1])
            return [dx, dy]
        else:
            return [0, 0]
    else:
        # Territory control: move towards unclaimed territory
        for y_idx, row in enumerate(territory_map):
            for x_idx, cell in enumerate(row):
                if cell != 'owned':
                    target_x, target_y = x_idx, y_idx
                    dx, dy = move_towards(target_x, target_y)
                    return [dx, dy]
        # All territory owned or no info, stay
        return [0, 0]
